ST.xhtml:
model.actualStatus := THIS^.actualStatus;
model.actual := THIS^.actual;
model.average := THIS^.average;
model.underrange := THIS^.underrange;
model.overrange := THIS^.overrange;
model.stat := THIS^.stat;

stat.enabled := F_EnabledStatus(
    superState := TRUE,
    isEnabled := config.enabled);
stat.health := F_HealthStatus( superState := TRUE );
stat.busy := F_BusyStatus(
    superState := TRUE,
    isBusy := proc.start.stat.busy);
proc.start( isEnabled := config.enabled );
proc.stop();
proc.reset();

THIS^.proc.start._copyFromModel_Process( model := model.proc.start );
THIS^.proc.stop._copyFromModel_Process( model := model.proc.stop );
THIS^.proc.reset._copyFromModel_Process( model := model.proc.reset );

model.actualStatus := THIS^.actualStatus;
model.setPointRamped := THIS^.setPointRamped;
model.power := THIS^.power;
model.associatedTemperature := THIS^.associatedTemperature;
model.setPointDeviation := THIS^.setPointDeviation;
model.isControlled := THIS^.isControlled;
model.stat := THIS^.stat;
THIS^.proc.start._copyToModel_Process( model := model.proc.start );
THIS^.proc.stop._copyToModel_Process( model := model.proc.stop );
THIS^.proc.reset._copyToModel_Process( model := model.proc.reset );

stat.health := F_HealthStatus(
    superState := TRUE,
    isGood := ((stat.health = HealthStatus.good) OR (stat.health = HealthStatus.warning)) AND ((stat.health = HealthStatus.good) OR (stat.health = HealthStatus.warning)));
proc.initialize( isEnabled := (NOT(stat.init = InitializationStatus.locked)) AND ((stat.init = InitializationStatus.shutdown) OR ((stat.init = InitializationStatus.initializingFailed) OR (stat.init = InitializationStatus.initialized))) );
proc.start( isEnabled := (stat.init = InitializationStatus.initializingFailed) AND (stat.init = InitializationStatus.initialized) );
proc.stop( isEnabled := (stat.busy = BusyStatus.busy) OR isControlled );
proc.reset( isEnabled := (stat.busy = BusyStatus.idle) AND (stat.init = InitializationStatus.initialized) );

THIS^.proc.initialize._copyFromModel_Process( model := model.proc.initialize );
THIS^.proc.start._copyFromModel_Process( model := model.proc.start );
THIS^.proc.stop._copyFromModel_Process( model := model.proc.stop );
THIS^.proc.reset._copyFromModel_Process( model := model.proc.reset );

model.actualStatus := THIS^.actualStatus;
model.config := THIS^.config;
model.isControlled := THIS^.isControlled;
model.setPointRamped := THIS^.setPointRamped;
model.temperatureSensor := THIS^.temperatureSensor;
model.vesselHeater := THIS^.vesselHeater;
model.stat := THIS^.stat;
THIS^.proc.initialize._copyToModel_Process( model := model.proc.initialize );
THIS^.proc.start._copyToModel_Process( model := model.proc.start );
THIS^.proc.stop._copyToModel_Process( model := model.proc.stop );
THIS^.proc.reset._copyToModel_Process( model := model.proc.reset );
